{
  "decline_reason": "",
  "claims": [
    {
      "text": "Under the Manual’s practice, when deferment terminates, the acceptance period resumes with the same amount of time remaining as was left when the deferment request was filed; it does not restart as a fresh acceptance period.",
      "quotes": [
        {
          "ref": "TMM/Part17/1#1",
          "quote": "After termination of deferment, the amount of time that is left of the time period for acceptance will be the amount of time that was left at the date the request for deferment of acceptance was filed."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "If deferment rests on multiple grounds, it terminates only when the last ground has been finalised.",
      "quotes": [
        {
          "ref": "TMM/Part17/3#1~3",
          "quote": "3.14 Where the deferment is based on multiple grounds, the deferment will be terminated when the last ground for deferment has been finalised."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "On termination, an automatic notice to the address for service provides the new acceptance due date and advises on further submissions or extensions of time if needed.",
      "quotes": [
        {
          "ref": "TMM/Part17/3#1~3",
          "quote": "3.16 On termination of deferment, a standard notice will be automatically sent to the address for service stating that deferment has been terminated. The notice will also provide the new acceptance due date and advise the applicant to notify the Registrar if the application is now clear to be accepted or make further submissions, if there are still outstanding matters, or to apply for further extensions of time for acceptance, if needed."
        }
      ],
      "authority": "manual"
    }
  ],
  "declined": false,
  "concepts_used": [
    "GC-0096",
    "GC-0093",
    "GC-0097"
  ]
}
